  ('DE-3', 'de-potsdam', 'it', 'Potsdam', 'Città del Brandeburgo con residenze prussiane e parchi storici.', 'Accesso, trasferimenti e accessibilità da verificare sulla fonte del luogo.', 'Aperture, condizioni e necessità di prenotazione da verificare per le date del viaggio.', null, null, null, null, null),
